/**
 * Node to represent nodes that are not shown. After showing a handful of symbol nodes
 * with the same name, this node will be used in place of the rest of the nodes and
 * will display "xx more..." where xx is the number of nodes that are not being shown. 
 * 
 */
public class MoreNode : SymbolTreeNode {
	private static Icon ICON = Icons.MAKE_SELECTION_ICON;
	private int count;
	private string name;

	MoreNode(string name, int count) {
		this.name = name;
		this.count = count;
	}

	/* @Override */
	public string getName() {
		return count + " more...";
	}

	/* @Override */
	public bool canCut() {
		return false;
	}

	/* @Override */
	public bool canPaste(List<GTreeNode> pastedNodes) {
		return false;
	}

	/* @Override */
	public void setNodeCut(bool isCut) {
		throw new UnsupportedOperationException("Cannot cut an organization node");
	}

	/* @Override */
	public bool isCut() {
		return false;
	}

	/* @Override */
	public DataFlavor getNodeDataFlavor() {
		return null;
	}

	/* @Override */
	public bool supportsDataFlavors(DataFlavor[] dataFlavors) {
		return false;
	}

	/* @Override */
	public Namespace getNamespace() {
		return null;
	}

	/* @Override */
	public List<GTreeNode> generateChildren(TaskMonitor monitor)
    {
		// not used, children generated in constructor
		return null;
	}

	/* @Override */
	public Icon getIcon(bool expanded) {
		return ICON;
	}

	/* @Override */
	public string getToolTip() {
		return "There are " + count + " nodes named \"" +
			name + "\" not being shown";
	}

	/* @Override */
	public bool isLeaf() {
		return true;
	}

	void incrementCount() {
		count++;
	}

	void decrementCount() {
		count = Math.max(0, --count);
	}

	bool isEmpty() {
		return count == 0;
	}
}
